export function withoutDrivers(text: string): string {
  return text.split("\n").map((line) => {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith("#")) return line;
    const head = /^("(?:[^"\\]|\\.)*"|\S+)(\s+|$)/.exec(trimmed);
