  // old and new lines follow, so those lines are consumed by count: a removed line "-- note" is written "--- note"
  // and an added "++ note" is written "+++ note", and neither is a path. A count that is omitted means 1.
  let inHeader = true;
  let oldLeft = 0;
  let newLeft = 0;
