      const p = headerPath(line.slice(4));
      add(p === undefined ? `<unparseable diff header: ${line}>` : diffSidePath(p, "b/"));
    } else if (line.startsWith("rename from ") || line.startsWith("rename to ")) {
      const p = headerPath(line.replace(/^rename (?:from|to) /, ""));
