  for (;;) {
    const { done, value } = await reader.read();
    if (done) break;
    total += value.byteLength;
    if (total > maxBytes) {
      await reader.cancel();
      throw new Error("models.dev data is larger than the 30 MiB limit");
    }
    chunks.push(Buffer.from(value));
